/* KF_TASK2_MODEL_FULL_WIDTH_V1 */
#writing-root .t2-wrap.t2-lesson .t2-model,
#writing-root .t2-wrap.t2-lesson .t2-model > p {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
  box-sizing: border-box;
}
#writing-root .t2-wrap.t2-lesson:has(> .t2-panel > .t2-model),
#writing-root .t2-wrap.t2-lesson > .t2-panel:has(> .t2-model) {
  height: auto !important;
  max-height: none !important;
  min-height: 0 !important;
  overflow: visible !important;
}

/* KF_HIDE_LOCAL_SCHEDULE_NOTICE_V1 */
#kf-local-plan-controls { display: none !important; }

/* KF_SCHEDULE_COMPACT_DAYS_V2 */
#hub-content > details.plan-week {
  box-sizing: border-box; max-width: 100%; min-width: 0;
  padding: 8px 14px !important; margin-block: 8px !important;
}
#hub-content > details.plan-week[open] {
  max-height: min(700px, 80vh); max-height: min(700px, 80dvh);
  overflow: auto; overscroll-behavior: contain; scrollbar-gutter: stable;
}
#hub-content > details.plan-week > summary {
  font-size: 17px !important; line-height: 1.4; padding: 8px 0 !important;
  overflow-wrap: anywhere; position: static !important;
}
#hub-content > details.plan-week > .plan-task.kf-day-row {
  display: block !important; min-width: 0; padding: 0 !important; margin: 0 !important;
}
.plan-task.kf-day-row > div:first-of-type { display: none !important; }
.plan-task.kf-day-row:not(.kf-day-open) > .kf-day-content { display: none !important; }
.plan-task.kf-day-row > .kf-day-toggle {
  display: grid; grid-template-columns: 66px 100px minmax(0, 1fr) 16px;
  align-items: center; gap: 10px; width: 100%; min-height: 48px;
  border: 0; border-radius: 8px; padding: 9px 4px;
  background: transparent; color: inherit; font: inherit; font-size: 14px;
  text-align: left; cursor: pointer;
}
.kf-day-toggle:hover, .kf-day-toggle:focus-visible { background: color-mix(in srgb, currentColor 6%, transparent) !important; }
.kf-day-toggle:focus-visible { outline: 2px solid currentColor; outline-offset: -2px; }
.kf-day-day { font-weight: 750; }
.kf-day-date, .kf-day-progress { opacity: .72; }
.kf-day-progress { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kf-day-arrow { text-align: right; }
.kf-day-toggle[aria-expanded="true"] .kf-day-arrow { transform: rotate(90deg); }
.plan-task.kf-day-row > .kf-day-content {
  max-height: min(360px, 45vh); max-height: min(360px, 45dvh);
  overflow: auto; overscroll-behavior: contain; min-width: 0;
  padding: 6px 10px 14px !important; font-size: 14px; overflow-wrap: anywhere;
}
.kf-day-content > h3 { display: none; }
.kf-day-content > p { margin-block: 8px !important; }
@media (max-width: 600px) {
  #hub-content > details.plan-week { padding-inline: 10px !important; }
  .plan-task.kf-day-row > .kf-day-toggle { grid-template-columns: 58px minmax(0, 1fr) 14px; gap: 6px; }
  .kf-day-progress { grid-column: 1 / 3; font-size: 12px; }
  .kf-day-arrow { grid-column: 3; grid-row: 1 / 3; }
}

