/* KF_STUDY_FLOW_LIGHT_V1 */
#stage > .kf-study-complete {
  background: #f1f7fb !important; color: #20344c !important;
  border: 1px solid #d4e3ee !important; border-radius: 24px !important;
  padding: 32px !important; text-align: left !important; margin: 12px 0 !important;
}
.kf-complete-heading { text-align: center; margin-bottom: 22px; }
.kf-complete-check { display: inline-grid; place-items: center; width: 48px; height: 48px; border-radius: 16px; background: #c9f1df; color: #147758; font-size: 26px; font-weight: 800; }
.kf-complete-heading p { color: #48816f !important; font-size: 11px; letter-spacing: .12em; font-weight: 800; margin: 14px 0 8px !important; }
.kf-complete-heading h2 { color: #20344c !important; font-size: clamp(23px,3vw,30px); margin: 0 0 8px; }
.kf-complete-heading > span:last-child { font-size: 14px; color: #5b7287; }
#stage > .kf-study-complete > strong { display: block; text-align: center; font-size: 14px; color: #4b6378; }
#stage > .kf-study-complete > p { text-align: center; color: #587086 !important; margin: 8px 0 !important; font-size: 13px; }
.kf-next-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; max-width: 1000px; margin: 24px auto; }
.kf-next-card { display: flex; align-items: center; gap: 14px; padding: 17px; border: 1px solid #d8e5ee; border-radius: 16px; background: #fff; color: #20344c !important; text-decoration: none !important; min-width: 0; }
