.kf-next-card:focus-visible { outline: 3px solid #517cf0; outline-offset: 2px; }
.kf-next-icon { display: grid; place-items: center; flex: 0 0 52px; height: 48px; border-radius: 12px; font-size: 10px; font-weight: 850; color: #315bb0; background: #e8edff; }
